// --------------------------------------
// Entry point (aka main)
// --------------------------------------
void start(void) {
  // Init
  struct event_loop loop;
  struct window w;

  event_loop_init(&loop);
  window_init(&w, 0 /*is_full_screen*/);

  const GLubyte* version_cstr = glGetString(GL_VERSION);
  print_cstr(STDOUT, "OpenGL version: \n");
  print_cstr(STDOUT, (const char *)version_cstr);
  print_cstr(STDOUT, "\n\n");
  print_cstr(STDOUT, "<Press ESC to exit>\n");

  GLuint sprite_prog = create_gl_shader_program(
    s_sprite_vert_src,
    s_sprite_frag_src
  );

  f32 aspect  = w.rect[2] / w.rect[3];
  f32 iaspect = 1.0f / aspect;

  GLuint vao;
  GLuint pos_bo;
  GLuint col_bo;
  GLuint scale_bo;
  GLuint tile_level_bo;
  GLuint scale_u_bo;
  glGenVertexArrays(1, &vao);
  glGenBuffers(1, &pos_bo);
  glGenBuffers(1, &col_bo);
  glGenBuffers(1, &scale_bo);
  glGenBuffers(1, &tile_level_bo);
  glGenBuffers(1, &scale_u_bo);

  glUseProgram(sprite_prog);
  glBindVertexArray(vao);

  // Vertices
  GLuint tile_tx;
  glGenTextures(1, &tile_tx);
  glBindTexture(GL_TEXTURE_2D_ARRAY, tile_tx);
  glTexStorage3D(GL_TEXTURE_2D_ARRAY, 1, GL_RGBA8, TILE_W, TILE_H,
      TILE_LEVEL_COUNT);
  glTexSubImage3D(GL_TEXTURE_2D_ARRAY, 0, 0, 0, 0, TILE_W, TILE_H,
      TILE_LEVEL_COUNT, GL_RGBA, GL_UNSIGNED_BYTE, s_tilemap_data);
  glTexParameteri(GL_TEXTURE_2D_ARRAY, GL_TEXTURE_WRAP_S, GL_REPEAT);
  glTexParameteri(GL_TEXTURE_2D_ARRAY, GL_TEXTURE_WRAP_T, GL_REPEAT);
  glTexParameteri(GL_TEXTURE_2D_ARRAY, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
  glTexParameteri(GL_TEXTURE_2D_ARRAY, GL_TEXTURE_MAG_FILTER, GL_NEAREST);

  glUniform1i(glGetUniformLocation(sprite_prog, "tile_tx"), 0);
  glUniform2f(glGetUniformLocation(sprite_prog, "size"), SPRITE_SIZE,
      SPRITE_SIZE);
  glUniform1f(glGetUniformLocation(sprite_prog, "iaspect"), iaspect);

  glBindBuffer(GL_ARRAY_BUFFER, pos_bo);
  glBufferData(GL_ARRAY_BUFFER, sizeof(s_sprites.pos), s_sprites.pos,
      GL_STATIC_DRAW);
  glVertexAttribPointer(1, 3, GL_FLOAT, GL_FALSE, 0, 0);
  glVertexAttribDivisor(1, 1);
  glEnableVertexAttribArray(1);

  glBindBuffer(GL_ARRAY_BUFFER, col_bo);
  glBufferData(GL_ARRAY_BUFFER, sizeof(s_sprites.col), s_sprites.col,
      GL_STATIC_DRAW);
  glVertexAttribPointer(2, 4, GL_FLOAT, GL_FALSE, 0, 0);
  glVertexAttribDivisor(2, 1);
  glEnableVertexAttribArray(2);

  glBindBuffer(GL_ARRAY_BUFFER, scale_bo);
  glBufferData(GL_ARRAY_BUFFER, sizeof(s_sprites.scale), s_sprites.scale,
      GL_STATIC_DRAW);
  glVertexAttribPointer(3, 2, GL_FLOAT, GL_FALSE, 0, 0);
  glVertexAttribDivisor(3, 1);
  glEnableVertexAttribArray(3);

  glBindBuffer(GL_ARRAY_BUFFER, tile_level_bo);
  glBufferData(GL_ARRAY_BUFFER, sizeof(s_sprites.anim_level),
      s_sprites.anim_level, GL_STATIC_DRAW);
  glVertexAttribPointer(4, 1, GL_INT, GL_FALSE, 0, 0);
  glVertexAttribDivisor(4, 1);
  glEnableVertexAttribArray(4);

  glBindBuffer(GL_ARRAY_BUFFER, scale_u_bo);
  glBufferData(GL_ARRAY_BUFFER, sizeof(s_sprites.scale_u), s_sprites.scale_u,
      GL_STATIC_DRAW);
  glVertexAttribPointer(5, 1, GL_FLOAT, GL_FALSE, 0, 0);
  glVertexAttribDivisor(5, 1);
  glEnableVertexAttribArray(5);
  // Logic
  // Scale bounds normalized to [-1;1] to match monitor aspect ratio
  f32 bounds[4] = {
    -1.0f * aspect + SPRITE_COLLISION_SIZE_05,
     1.0f * aspect - SPRITE_COLLISION_SIZE_05,
    -1.0f          + SPRITE_COLLISION_SIZE_05,
     1.0f          - SPRITE_COLLISION_SIZE_05,
  };

  struct xorshift64_state vel_st  = {137382305742834};
  struct xorshift64_state pos_st  = {235936748814573};
  struct xorshift64_state dir_st  = {323687463988431};

  // Spawn
  for (i32 idx = 0; idx < LOVERS_COUNT; ++idx) {
    i32 i       = idx;
    s_sprites.anim_idx[i * 1 + 0]       = ANIM_LOVER_WALK;
    s_sprites.anim_t[i * 1 + 0]         = (f32)i / SPRITES_COUNT;
    s_sprites.scale[i * 2 + 0]          = 1.0f;
    s_sprites.scale[i * 2 + 1]          = 1.0f;
    s_sprites.scale_u[i * 1 + 1]        = 1.0f;
    s_sprites.dir_time[i * 1 + 0]       = SPRITE_CHANGE_DIR_TIME_MAX;
    s_sprites.state[i * 1 + 0].flags    = SPRITE_STATE_LOVER |
      SPRITE_STATE_COLLIDE | SPRITE_STATE_MOVE | SPRITE_STATE_CHANGE_DIR |
      SPRITE_STATE_ANIM_VEL_SCALE;
  }

  for (i32 idx = 0; idx < STRANGERS_COUNT; ++idx) {
    i32 i                               = idx + LOVERS_COUNT;
    f32 kdir                            = xorshift64(&dir_st) / (f32)U64_MAX;
    s_sprites.anim_idx[i * 1 + 0]       = ANIM_STRANGER_WALK;
    s_sprites.anim_t[i * 1 + 0]         = (f32)i / SPRITES_COUNT;

    s_sprites.scale[i * 2 + 0]          = 1.0f;
    s_sprites.scale[i * 2 + 1]          = 1.0f;

    s_sprites.scale_u[i * 1 + 1]        = 1.0f;

    s_sprites.dir_time[i * 1 + 0]       =
      lerpf32(kdir, -SPRITE_IDLE_TIME, SPRITE_CHANGE_DIR_TIME_MAX);

    s_sprites.state[i * 1 + 0].flags =
      SPRITE_STATE_CHANGE_DIR | SPRITE_STATE_ANIM_VEL_SCALE;
  }

  for (i32 idx = 0; idx < BUSHES_COUNT; ++idx) {
    i32 i                               = idx + LOVERS_COUNT + STRANGERS_COUNT;
    f32 kpos0                           = xorshift64(&pos_st) / (f32)U64_MAX;
    f32 kpos1                           = xorshift64(&pos_st) / (f32)U64_MAX;
    s_sprites.pos[i * 3 + 0]            = lerpf32(kpos0, bounds[0], bounds[1]);
    s_sprites.pos[i * 3 + 1]            = lerpf32(kpos1, bounds[2], bounds[3]);
    s_sprites.pos[i * 3 + 2]            = (f32)i / SPRITES_COUNT;
    s_sprites.anim_idx[i * 1 + 0]       = ANIM_BUSH;
    s_sprites.anim_t[i * 1 + 0]         = (f32)i / SPRITES_COUNT;
    s_sprites.scale[i * 2 + 0]          = 1.0f;
    s_sprites.scale[i * 2 + 1]          = 1.0f;
    s_sprites.scale_u[i * 1 + 1]        = 1.0f;
    s_sprites.state[i * 1 + 0].flags    = 0;

    s_sprites.col[i * 4 + 0]            = s_col_palettes[0][0];
    s_sprites.col[i * 4 + 1]            = s_col_palettes[0][1];
    s_sprites.col[i * 4 + 2]            = s_col_palettes[0][2];
    s_sprites.col[i * 4 + 3]            = s_col_palettes[0][3];
  }

  // Level
  {
    // Lovers start at borders facing each other
    EXPECT(SPRITES_COUNT >= LOVERS_COUNT, "There has to be at least one lover.");
    EXPECT(SPRITES_COUNT > 0, "There has to be at least 1 sprite");

    i32 first_lover_idx = PLAYER_IDX + 1;
    s_sprites.pos[first_lover_idx * 3 + 0] = bounds[1] - 0.25;
    s_sprites.pos[first_lover_idx * 3 + 1] = 0.0;
    s_sprites.vel[first_lover_idx * 2 + 0] = -SPRITE_VEL_MAX;
    s_sprites.vel[first_lover_idx * 2 + 1] = 0.0;
    s_sprites.pos[PLAYER_IDX * 3 + 0] = -0.3;
    s_sprites.pos[PLAYER_IDX * 3 + 1] = 0.0f;
    s_sprites.vel[PLAYER_IDX * 2 + 0] = 0.0f;
    s_sprites.vel[PLAYER_IDX * 2 + 1] = 0.0f;
    s_sprites.state[PLAYER_IDX].flags |= SPRITE_STATE_PLAYER;
    s_sprites.state[PLAYER_IDX].flags &= ~SPRITE_STATE_CHANGE_DIR;
  }

  enum level_state level_state  = LEVEL_STATE_SPAWN;
  i32 game_level = GAME_LEVEL_FIRST;
  i32 game_next_level = game_level;

  f32 fade_in_a = 0.0f;

  // Game loop
  f32 cpu_timer_freq  = read_cpu_timer_freq();
  f32 icpu_timer_freq = 1.0f / cpu_timer_freq;
  u64 tsc             = read_cpu_timer();

  f32 loop_s          = 0.0f;
  u64 loop_count      = 0;
  f32 print_dt_tsc    = tsc + 5.0f * cpu_timer_freq;

  f32 sim_dt          = 0.0f;

  f32 anim_level_state_transition_t  = 0.0f;

  while (1) {
    // dt bookkeeping
    u64 new_tsc     = read_cpu_timer();
    f32 dt          = (new_tsc - tsc) * icpu_timer_freq;
    tsc             = new_tsc;
    loop_s          += dt;
    loop_count      += 1;

#if 1 // Print average tick time (print could block io)
    if (tsc > print_dt_tsc) {
      print_avg_dt_fps(loop_s / loop_count);

      loop_s        = 0.0f;
      loop_count    = 0;
      print_dt_tsc  = tsc + 5.0f * cpu_timer_freq;
    }
#else
    (void)loop_s;
    (void)loop_count;
    (void)print_dt_tsc;
#endif
    // Update
    // Accumulate passed time and run simulation with fixed `SIM_TICK` dt
    // TODO: drop the frames
    sim_dt              += dt;
    i32 sim_tick_count  = sim_dt / SIM_TICK;
    sim_dt              = sim_dt - sim_tick_count * SIM_TICK;

    for (i32 sim_tick = 0; sim_tick < sim_tick_count; ++sim_tick) {
      // Keyboard Input
      // Step through event loop once, updating input events
      event_loop_step(&loop);

      // ESC to exit
      if (loop.keycodes.e[KC_ESC]) {
        goto shutdown;
      }

      anim_level_state_transition_t += SIM_TICK;

      // Transition to next level
      if (game_level != game_next_level) {
        game_level = game_next_level;
        level_state = LEVEL_STATE_DESPAWN;
      }

      {
        b32 is_nightmare = game_level >= GAME_LEVEL_NIGHTMARE_FIRST;
        i32 scale = is_nightmare
          ? GAME_LEVEL_STRANGERS_NIGHTMARE_SCALE
          : GAME_LEVEL_STRANGERS_SCALE;

        i32 enabled_strangers = MIN(game_level * scale, STRANGERS_COUNT);

        switch (level_state) {
          case LEVEL_STATE_PLAYING: break;

          case LEVEL_STATE_DESPAWN:
            for (i32 i = 0; i < LOVERS_COUNT + STRANGERS_COUNT; ++i) {
              s_sprites.state[i * 1 + 0].flags |=   SPRITE_STATE_SCALE_UP;
              s_sprites.state[i * 1 + 0].flags |=   SPRITE_STATE_FADE_OUT;
              s_sprites.state[i * 1 + 0].flags &=   ~SPRITE_STATE_FADE_IN;
              s_sprites.state[i * 1 + 0].flags &=   ~SPRITE_STATE_COLLIDE;
              s_sprites.state[i * 1 + 0].flags &=   ~SPRITE_STATE_MOVE;
            }

            anim_level_state_transition_t = 0.0f;
            ++level_state;
          break;

          case LEVEL_STATE_DESPAWNING:
            if (anim_level_state_transition_t > 0.5f) {
              anim_level_state_transition_t = 0.0f;
              ++level_state;
            }
          break;

          case LEVEL_STATE_RANDOMIZE: {
            // Reset plaers speed
            i32 i = 0;
            for (; i < PLAYER_COUNT; ++i) {
              f32 kpos0   = xorshift64(&pos_st) / (f32)U64_MAX;
              f32 kpos1   = xorshift64(&pos_st) / (f32)U64_MAX;
              s_sprites.pos[i * 3 + 0]  = lerpf32(kpos0, bounds[0], bounds[1]);
              s_sprites.pos[i * 3 + 1]  = lerpf32(kpos1, bounds[2], bounds[3]);
              s_sprites.vel[i * 2 + 0]  = 0.0f;
              s_sprites.vel[i * 2 + 1]  = 0.0f;
            }

            for (; i < LOVERS_COUNT + enabled_strangers; ++i) {
              f32 kpos0   = xorshift64(&pos_st) / (f32)U64_MAX;
              f32 kpos1   = xorshift64(&pos_st) / (f32)U64_MAX;
              f32 kvel0   = xorshift64(&vel_st) / (f32)U64_MAX;
              f32 kvel1   = xorshift64(&vel_st) / (f32)U64_MAX;
              s_sprites.pos[i * 3 + 0]  = lerpf32(kpos0, bounds[0], bounds[1]);
              s_sprites.pos[i * 3 + 1]  = lerpf32(kpos1, bounds[2], bounds[3]);
              s_sprites.vel[i * 2 + 0]  =
                lerpf32(kvel0, -SPRITE_VEL_MAX, SPRITE_VEL_MAX);
              s_sprites.vel[i * 2 + 1]  =
                lerpf32(kvel1, -SPRITE_VEL_MAX, SPRITE_VEL_MAX);
            }

            ++level_state;
          } break;

          case LEVEL_STATE_SPAWN: {
            for (i32 i = 0; i < LOVERS_COUNT + enabled_strangers; ++i) {
              b32 is_lover = is_bit_set(
                  s_sprites.state[i * 1 + 0].flags, SPRITE_STATE_LOVER);

              i32 palette = is_nightmare ? NIGHTMARE_PALETTE : is_lover
                ? i % LOVER_PALETTE_COUNT
                : LOVER_PALETTE_COUNT + i % (PALETTE_COUNT -
                    LOVER_PALETTE_COUNT);

              s_sprites.state[i * 1 + 0].flags    |= SPRITE_STATE_FADE_IN;
              s_sprites.state[i * 1 + 0].flags    |= SPRITE_STATE_COLLIDE;
              s_sprites.state[i * 1 + 0].flags    |= SPRITE_STATE_MOVE;
              s_sprites.state[i * 1 + 0].flags    &= ~SPRITE_STATE_FADE_OUT;
              s_sprites.state[i * 1 + 0].flags    &= ~SPRITE_STATE_SCALE_UP;
              s_sprites.state[i * 1 + 0].flags    &= ~SPRITE_STATE_DISABLED;

              s_sprites.state[i * 1 + 0].palette  = palette;
              s_sprites.col[i * 4 + 0]            = s_col_palettes[palette][0];
              s_sprites.col[i * 4 + 1]            = s_col_palettes[palette][1];
              s_sprites.col[i * 4 + 2]            = s_col_palettes[palette][2];
              s_sprites.col[i * 4 + 3]            = 0.0f;

              s_sprites.scale[i * 2 + 0]          = 1.0f;
              s_sprites.scale[i * 2 + 1]          = 1.0f;
            }
            level_state = LEVEL_STATE_PLAYING;
          } break;
        }
      }

      // Player controls
      f32 PLAYER_CONTROL_VEL = 2.0f * SIM_TICK;
      f32 vel[2];
      vel[0] = s_sprites.vel[PLAYER_IDX * 2 + 0];
      vel[1] = s_sprites.vel[PLAYER_IDX * 2 + 1];
      // Dampen
      vel[0] *= 0.95; // TODO: powf32 SIM_TICK
      vel[1] *= 0.95;

      if (loop.keycodes.e[KC_LEFT]) {
        vel[0] -= PLAYER_CONTROL_VEL;
      }
      if (loop.keycodes.e[KC_RIGHT]) {
        vel[0] += PLAYER_CONTROL_VEL;
      }
      if (loop.keycodes.e[KC_DOWN]) {
        vel[1] -= PLAYER_CONTROL_VEL;
      }
      if (loop.keycodes.e[KC_UP]) {
        vel[1] += PLAYER_CONTROL_VEL;
      }

      vel[0] = clampf32(vel[0], -SPRITE_VEL_MAX, SPRITE_VEL_MAX);
      vel[1] = clampf32(vel[1], -SPRITE_VEL_MAX, SPRITE_VEL_MAX);
      s_sprites.vel[PLAYER_IDX * 2 + 0] = vel[0];
      s_sprites.vel[PLAYER_IDX * 2 + 1] = vel[1];

      fade_in_a = clampf32(fade_in_a + 1.0f * SIM_TICK, 0.0f, 1.0f);

      // Circle collisions
      f32 radii         = SPRITE_COLLISION_SIZE_05 + SPRITE_COLLISION_SIZE_05;
      f32 radii2        = radii * radii;
      f32 match_radii2  = radii * radii * 0.25f;

      for (i32 i = 0; i < SPRITES_COUNT - 1; ++i) {
        struct sprite_state state0;
        f32 pos0[2];
        f32 vel0[2];

        state0    = s_sprites.state[i * 1 + 0];
        pos0[0]   = s_sprites.pos[i * 3 + 0];
        pos0[1]   = s_sprites.pos[i * 3 + 1];
        vel0[0]   = s_sprites.vel[i * 2 + 0];
        vel0[1]   = s_sprites.vel[i * 2 + 1];

        if (!is_bit_set(state0.flags, SPRITE_STATE_COLLIDE)) {
          continue;
        }
        if (is_bit_set(state0.flags, SPRITE_STATE_DISABLED)) {
          continue;
        }

        for (i32 j = i + 1; j < SPRITES_COUNT; ++j) {
          struct sprite_state state1;
          f32 pos1[2];
          f32 vel1[2];
          f32 d[2];           // distance between centers
          f32 dunit[2];       // normalized d
          f32 depth;
          f32 dlen;
          f32 dlen2;

          state1    = s_sprites.state[j * 1 + 0];
          pos1[0]   = s_sprites.pos[j * 3 + 0];
          pos1[1]   = s_sprites.pos[j * 3 + 1];
          vel1[0]   = s_sprites.vel[j * 2 + 0];
          vel1[1]   = s_sprites.vel[j * 2 + 1];

          if (!is_bit_set(state1.flags, SPRITE_STATE_COLLIDE)) {
            continue;
          }
          if (is_bit_set(state1.flags, SPRITE_STATE_DISABLED)) {
            continue;
          }

          d[0]      = pos1[0] - pos0[0];
          d[1]      = pos1[1] - pos0[1];
          dlen2     = d[0] * d[0] + d[1] * d[1];

          if (dlen2 < radii2) {
            // Lovers merge, the rest collide
            b32 match_lovers = is_bit_set(state0.flags & state1.flags,
                SPRITE_STATE_LOVER);
            b32 close_to_match = dlen2 < match_radii2;

            if (match_lovers) {
              // Matching lovers
              if (close_to_match) {
                game_next_level = game_level + GAME_LEVEL_INCREMENT;
              }
            } else {
              // Collision and repulsion
              // Depth and normal of collision intesection
              dlen     = sqrtf32(dlen2);
              depth    = radii - dlen;
              dunit[0] = d[0] / dlen;
              dunit[1] = d[1] / dlen;

              pos0[0]  += dunit[0] * depth * -0.5;
              pos0[1]  += dunit[1] * depth * -0.5;
              pos1[0]  += dunit[0] * depth *  0.5;
              pos1[1]  += dunit[1] * depth *  0.5;
            }
          }

          s_sprites.pos[i * 3 + 0]        = pos0[0];
          s_sprites.pos[i * 3 + 1]        = pos0[1];
          s_sprites.vel[i * 2 + 0]        = vel0[0];
          s_sprites.vel[i * 2 + 1]        = vel0[1];

          s_sprites.pos[j * 3 + 0]        = pos1[0];
          s_sprites.pos[j * 3 + 1]        = pos1[1];
          s_sprites.vel[j * 2 + 0]        = vel1[0];
          s_sprites.vel[j * 2 + 1]        = vel1[1];
        }
      }

      for (i32 i = 0; i < SPRITES_COUNT; ++i) {
        // Scale, fade, bounds collision
        struct sprite_state state;
        f32 pos_prev[2];
        f32 pos[2];
        f32 vel[2];
        f32 col[4];
        f32 scale[2];
        f32 scale_u;
        i32 dmask[2];
        f32 dir_time;
        // Animaiton
        i32 anim_idx;
        f32 anim_t;
        f32 anim_dt = 0; // anim_dt will be scaled according to animation fps

        state           = s_sprites.state[i * 1 + 0];
        pos_prev[0]     = s_sprites.pos_prev[i * 3 + 0];
        pos_prev[1]     = s_sprites.pos_prev[i * 3 + 1];
        pos[0]          = s_sprites.pos[i * 3 + 0];
        pos[1]          = s_sprites.pos[i * 3 + 1];
        vel[0]          = s_sprites.vel[i * 2 + 0];
        vel[1]          = s_sprites.vel[i * 2 + 1];
        col[0]          = s_sprites.col[i * 4 + 0];
        col[1]          = s_sprites.col[i * 4 + 1];
        col[2]          = s_sprites.col[i * 4 + 2];
        col[3]          = s_sprites.col[i * 4 + 3];
        scale[0]        = s_sprites.scale[i * 2 + 0];
        scale[1]        = s_sprites.scale[i * 2 + 1];
        scale_u         = s_sprites.scale_u[i * 1 + 0];
        dir_time        = s_sprites.dir_time[i * 1 + 0];

        anim_idx        = s_sprites.anim_idx[i * 1 + 0];
        anim_t          = s_sprites.anim_t[i * 1 + 0];

        if (is_bit_set(state.flags, SPRITE_STATE_DISABLED)) {
          continue;
        }

        // Idle and Change direction of movement from time to time
        dir_time      -= SIM_TICK;
        if (is_bit_set(state.flags, SPRITE_STATE_CHANGE_DIR)) {
          if (dir_time < 0.0f) {
            // Idle
            state.flags &= ~SPRITE_STATE_MOVE;
          }
          if (dir_time < SPRITE_IDLE_TIME) {
            // Change direction
            f32 kdir    = xorshift64(&dir_st) / (f32)U64_MAX;
            f32 kvel0   = xorshift64(&vel_st) / (f32)U64_MAX;
            f32 kvel1   = xorshift64(&vel_st) / (f32)U64_MAX;
            vel[0]      = lerpf32(kvel0, -SPRITE_VEL_MAX, SPRITE_VEL_MAX);
            vel[1]      = lerpf32(kvel1, -SPRITE_VEL_MAX, SPRITE_VEL_MAX);
            dir_time    = lerpf32(kdir, SPRITE_CHANGE_DIR_TIME_MIN,
                SPRITE_CHANGE_DIR_TIME_MAX);
            state.flags |= SPRITE_STATE_MOVE;
          }
        }

        if (is_bit_set(state.flags, SPRITE_STATE_MOVE)) {
          pos[0]        += vel[0] * SIM_TICK;
          pos[1]        += vel[1] * SIM_TICK;
          // Change direction on colliding with bounds
          dmask[0]      = pos[0] < bounds[0] || pos[0] > bounds[1];
          dmask[1]      = pos[1] < bounds[2] || pos[1] > bounds[3];
          vel[0]        *= (1 - (dmask[0] << 1));
          vel[1]        *= (1 - (dmask[1] << 1));
          pos[0]        = clampf32(pos[0], bounds[0], bounds[1]);
          pos[1]        = clampf32(pos[1], bounds[2], bounds[3]);

          scale_u       = vel[0] < 0.0f ? -1.0f : 1.0f;

          // Change direction on colliding with bounds
          dmask[0]      = pos[0] < bounds[0] || pos[0] > bounds[1];
          dmask[1]      = pos[1] < bounds[2] || pos[1] > bounds[3];
        }

        if (is_bit_set(state.flags, SPRITE_STATE_SCALE_UP)) {
          scale[0]      += SPRITE_SCALE_VEL;
          scale[1]      += SPRITE_SCALE_VEL;

          if (scale[0] >= 3.0f) {
            state.flags &= ~SPRITE_STATE_SCALE_UP;
            scale[0]      = 1.0f;
            scale[1]      = 1.0f;
          }
        }

        if (is_bit_set(state.flags, SPRITE_STATE_FADE_IN)) {
          col[3] *= 1.08f;
          col[3] = MAX(col[3], 0.15f); // so multiplication above works
          if (col[3] >= 1.0f) {
            state.flags &= ~SPRITE_STATE_FADE_IN;
          }
        }

        if (is_bit_set(state.flags, SPRITE_STATE_FADE_OUT)) {
          col[3] *= 0.75f;
          if (col[3] < 0.001f) {
              state.flags &= ~SPRITE_STATE_FADE_OUT;
              col[3] = 0.0f;
          }
        }
        col[3] = clampf32(col[3], 0.0f, 1.0f);

        // Animation tile calcualtion

        if (is_bit_set(state.flags, SPRITE_STATE_ANIM_VEL_SCALE)) {
          // Animate walk animation even when simple repulsion is in action
          // (there is no velocity involved)

          // Velocity calculated from position change in this frame
          f32 dposdt[2];
          dposdt[0] = (pos[0] - pos_prev[0]) / SIM_TICK;
          dposdt[1] = (pos[1] - pos_prev[1]) / SIM_TICK;

          f32 abs_dposdt =
            sqrtf32(dposdt[0] * dposdt[0] + dposdt[1] * dposdt[1]);
          // Only based on X velocity
          scale_u = dposdt[0] > -0.1f && dposdt[0] < 0.1f
            ? scale_u
            : dposdt[0] > 0.1 ? 1.0f : -1.0f;

          anim_dt = SIM_TICK * abs_dposdt;
          if (abs_dposdt < 0.001f) {
            anim_dt = 0.0f;
            anim_t = 0.0f; // t == 0 -> frame == 0 -> standing still
          }
        } else {
          anim_dt += SIM_TICK;
        }

        struct anim anim = s_anims[anim_idx];
        anim_t = fmodf32(anim_t + anim_dt * anim.fps / anim.count, 1.0f);
        i32 anim_level = anim.offset + anim_t * anim.count;

        s_sprites.pos_prev[i * 3 + 0]   = pos[0];
        s_sprites.pos_prev[i * 3 + 1]   = pos[1];
        s_sprites.pos[i * 3 + 0]        = pos[0];
        s_sprites.pos[i * 3 + 1]        = pos[1];
        s_sprites.vel[i * 2 + 0]        = vel[0];
        s_sprites.vel[i * 2 + 1]        = vel[1];
        s_sprites.col[i * 4 + 0]        = col[0];
        s_sprites.col[i * 4 + 1]        = col[1];
        s_sprites.col[i * 4 + 2]        = col[2];
        s_sprites.col[i * 4 + 3]        = col[3];
        s_sprites.scale[i * 2 + 0]      = scale[0];
        s_sprites.scale[i * 2 + 1]      = scale[1];
        s_sprites.scale_u[i * 1 + 0]    = scale_u;
        s_sprites.dir_time[i * 1 + 0]   = dir_time;
        s_sprites.state[i * 1 + 0]      = state;
        s_sprites.anim_level[i * 1 + 0] = anim_level;
        s_sprites.anim_t[i * 1 + 0]     = anim_t;
      }
    }

    // Draw
    glClearColor(0.34, 0.44f, 0.25, fade_in_a);
    glClear(GL_COLOR_BUFFER_BIT);
    glEnable(GL_BLEND);
    glBlendFunc(GL_ONE, GL_ONE_MINUS_SRC_ALPHA);

    // Draw sprites
    glBindBuffer(GL_ARRAY_BUFFER, pos_bo);
    glBufferSubData(GL_ARRAY_BUFFER, 0, sizeof(s_sprites.pos), s_sprites.pos);

    glBindBuffer(GL_ARRAY_BUFFER, col_bo);
    glBufferSubData(GL_ARRAY_BUFFER, 0, sizeof(s_sprites.col), s_sprites.col);

    glBindBuffer(GL_ARRAY_BUFFER, scale_bo);
    glBufferSubData(GL_ARRAY_BUFFER, 0, sizeof(s_sprites.scale),
        s_sprites.scale);

    glBindBuffer(GL_ARRAY_BUFFER, tile_level_bo);
    glBufferSubData(GL_ARRAY_BUFFER, 0, sizeof(s_sprites.anim_level),
        s_sprites.anim_level);

    glBindBuffer(GL_ARRAY_BUFFER, scale_u_bo);
    glBufferSubData(GL_ARRAY_BUFFER, 0, sizeof(s_sprites.scale_u),
        s_sprites.scale_u);

    glDrawArraysInstanced(GL_TRIANGLE_STRIP, 0, 4, SPRITES_COUNT);

    window_flush(&w);
  }
  print_avg_dt_fps(loop_s / loop_count);

shutdown:
  // Shutdown
  glDeleteShader(sprite_prog);

  glDeleteBuffers(1, &pos_bo);
  glDeleteBuffers(1, &col_bo);
  glDeleteBuffers(1, &scale_bo);
  glDeleteBuffers(1, &tile_level_bo);
  glDeleteBuffers(1, &scale_u_bo);
  glDeleteVertexArrays(1, &vao);

  window_shutdown(&w);
  event_loop_shutdown(&loop);

  exit(0);
}
